-- Repair approval tokens from compatibility JSON snapshots.
update public.expense_requests set president_approval_token=coalesce(president_approval_token,nullif(data->>'presidentApprovalToken','')), president_approval_token_expires_at=coalesce(president_approval_token_expires_at,nullif(data->>'presidentApprovalTokenExpiresAt','')::timestamptz) where status='Pending President Recommendation' and (president_approval_token is null or president_approval_token_expires_at is null);
update public.expense_requests set final_approval_token=coalesce(final_approval_token,nullif(data->>'finalApprovalToken','')), final_approval_token_expires_at=coalesce(final_approval_token_expires_at,nullif(data->>'finalApprovalTokenExpiresAt','')::timestamptz) where status='Pending Final Approval' and (final_approval_token is null or final_approval_token_expires_at is null);
